def max_sub_array(nums: list[int]) -> tuple[int, list[int]]:
    if not nums:
        return (0, [])

    max_sum = float('-inf')
    current_sum = 0
    start = 0
    end = 0
    temp_start = 0

    for i, num in enumerate(nums):
        current_sum += num

        if current_sum > max_sum:
            max_sum = current_sum
            start = temp_start
            end = i

        if current_sum < 0:
            current_sum = 0
            temp_start = i + 1

    return (max_sum, nums[start:end+1])

# Example usage:
nums = [-2, 1, -3, 4, -1, 2, 1, -5, 4]
print(max_sub_array(nums))  # Output: (6, [4, -1, 2, 1])
